UPDATE som_listing
SET title = #{title}, description = #{description}, price = #{price}, original_price = #{originalPrice},
    marketplace_listing_id = #{marketplaceListingId}, quality_score = #{qualityScore},
    status = #{status}, updated_at = #{updatedAt}
WHERE listing_id = #{listingId} AND tenant_id = #{tenantId}

UPDATE som_channel_sku
SET status = #{status}, updated_at = #{updatedAt}
WHERE channel_sku_id = #{channelSkuId} AND tenant_id = #{tenantId}

