WHERE tenant_id = #{tenantId} AND channel_sku_id = #{channelSkuId}

SELECT channel_sku_id, tenant_id, product_sku, channel, channel_sku, store_id, marketplace_id, status, created_at, updated_at
FROM som_channel_sku
WHERE tenant_id = #{tenantId} AND product_sku = #{productSku} AND channel = #{channel} AND channel_sku = #{channelSku}

SELECT channel_sku_id, tenant_id, product_sku, channel, channel_sku, store_id, marketplace_id, status, created_at, updated_at
FROM som_channel_sku
WHERE tenant_id = #{tenantId}
  AND channel = #{channel}
  AND channel_sku = #{channelSku}


        AND store_id = #{storeId}


        AND store_id IS NULL




        AND marketplace_id = #{marketplaceId}


        AND marketplace_id IS NULL


ORDER BY updated_at DESC
LIMIT 1

