UPDATE som_price_rule
SET name = #{name}, type = #{type}, conditions = #{conditions}, actions = #{actions},
    min_price = #{minPrice}, max_price = #{maxPrice}, status = #{status}, updated_at = #{updatedAt}
WHERE rule_id = #{ruleId} AND tenant_id = #{tenantId}

